#include <stdio.h>
int main(void) {
    int values[] = {75, 95, 85, 100, 50};
    for (int pass = 0; pass < 4; ++pass) {
        for (int pos = 0; pos < 4 - pass; ++pos) {
            if (values[pos] > values[pos + 1]) {
                int saved = values[pos];
                values[pos] = values[pos + 1];
                values[pos + 1] = saved;
            }
        }
    }
    for (int pos = 0; pos < 5; ++pos) printf("%d ", values[pos]);
    return 0;
}

