        for (int i = 0; i < end; i++)
            if (a[i] < a[i+1]) {
                int t = a[i]; a[i] = a[i+1]; a[i+1] = t;
            }
    printf("%d %d %d", a[0], a[1], a[2]);
    return 0;
}

